return {["scripts/actions/abilities/pets/cyclotail.lua"]={["Path"]="scripts/actions/abilities/pets/cyclotail.lua",["SHA256"]="c2ac082d2244d7c3bc7dd54a00bf657702d8d05d6a3a5faf386d1513f2274021",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'cyclotail_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/dark_spore.lua"]={["Path"]="scripts/actions/abilities/pets/dark_spore.lua",["SHA256"]="a26d7d145918aff4d5d9ad581dccf5016c57867f88cf0f864fd51cb7d36edcff",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'dark_spore_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/deconstruction.lua"]={["Path"]="scripts/actions/abilities/pets/deconstruction.lua",["SHA256"]="307dea096841d3f017e7d64d6d943a9867497919e65613d3751ae14311ee6e6b",["Text"]="-----------------------------------\n-- Deconstruction\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    local effectCount = 0\n    local effectID    = pet:stealStatusEffect(target) or 0\n    local newStatus   = pet:getStatusEffect(effectID) or nil\n\n    if newStatus then\n        -- Store the stolen effect ID for Chronoshift so we know what effect to transfer.\n        pet:setLocalVar('aEffectID', effectID)\n        target:delStatusEffectSilent(effectID)\n        petskill:setMsg(xi.msg.basic.MAGIC_EFFECT_DRAINED)\n        effectCount = 1\n    else\n        petskill:setMsg(xi.msg.basic.JA_NO_EFFECT_2)\n    end\n\n    target:addEnmity(pet, 1, 60)\n    target:addEnmity(summoner, 1, 0) -- this is to ensure you cannot cheese mobs with this, mob goes passive if not added\n\n    return effectCount\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/diamond_dust.lua"]={["Path"]="scripts/actions/abilities/pets/diamond_dust.lua",["SHA256"]="08df0ee8101191f3894ffbf9a81283bb408340566df1797ce63ee805415c746a",["Text"]="-----------------------------------\n-- Diamond Dust\n-- Family: Shiva (Player Pet)\n-- Note: Shiva's Astral Flow\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage      = pet:getMainLvl() + 2\n    params.fTP             = { 9.0, 9.0, 9.0 }\n    params.int_wSC         = 0.30\n    params.element         = xi.element.ICE\n    params.attackType      = xi.attackType.MAGICAL\n    params.damageType      = xi.damageType.ICE\n    params.shadowBehavior  = xi.mobskills.shadowBehavior.WIPE_SHADOWS\n    params.dStatMultiplier = 1.5\n    params.canMagicBurst   = true\n    params.primaryMessage  = xi.msg.basic.USES_JA_TAKE_DAMAGE\n    -- TODO: Should not consume TP\n\n    local info = xi.mobskills.mobMagicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    summoner:setMP(0)\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/double_claw.lua"]={["Path"]="scripts/actions/abilities/pets/double_claw.lua",["SHA256"]="502fc8fd8d4a9a281dece7dc8a25acbedc93861e7f910f7abe74db32557ccdc7",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'double_claw_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/double_punch.lua"]={["Path"]="scripts/actions/abilities/pets/double_punch.lua",["SHA256"]="311c6c33ae47dc31d6dc9ae0e336c8278e49d71373f7ffe294505d9c7d945f2d",["Text"]="-----------------------------------\n-- Double Punch\n-- Family: Avatar (Ifrit)\n-- Description: Delivers a twofold attack to a target.\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 2\n    params.fTP               = { 5.0, 5.0, 5.0 } -- TODO: Capture fTP scalings for 2000/3000 TP\n    params.fTPSubsequentHits = { 5.0, 5.0, 5.0 }\n    params.str_wSC           = 0.30\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.BLUNT\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_2\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/double_slap.lua"]={["Path"]="scripts/actions/abilities/pets/double_slap.lua",["SHA256"]="added49268417b45d9f5a14114789ba2bbe9beb1c08d9fa6f2da139d8dca992e",["Text"]="-----------------------------------\n-- Double Slap\n-- Family: Avatar (Shiva)\n-- Description: Delivers a two fold attack to a target.\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 2\n    params.fTP               = { 6.328125, 6.328125, 6.328125 }\n    params.fTPSubsequentHits = { 6.328125, 6.328125, 6.328125 }\n    params.str_wSC           = 0.30\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.BLUNT\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_2\n    -- params.accuracyModifier   = { 0, 0, 0 } TODO: Capture accuracy\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/drainkiss.lua"]={["Path"]="scripts/actions/abilities/pets/drainkiss.lua",["SHA256"]="166116eea31750438cb365f00169d20272a6db738fb058ffe87f02800dbc04a5",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'drainkiss_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/dream_flower.lua"]={["Path"]="scripts/actions/abilities/pets/dream_flower.lua",["SHA256"]="bd77d21a91b06ae4ceafb213585bbb46cdc6dc8ce474bae10c2c54eaf79ad38a",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'dream_flower_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/dream_shroud.lua"]={["Path"]="scripts/actions/abilities/pets/dream_shroud.lua",["SHA256"]="2c41d1e00d2ab1b2bce23681bb62ef4171e676ff806d50e8ea60953c0a1eaa34",["Text"]="-----------------------------------\n-- Dream Shroud\n-- Family: Avatar (Diabolos)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local baseDuration = 180\n    local bonusTime    = utils.clamp(summoner:getSkillLevel(xi.skill.SUMMONING_MAGIC) - 300, 0, 200)\n    local duration     = baseDuration + bonusTime\n    local hour         = VanadielHour()\n    local buffvalue    = math.abs(12 - hour) + 1\n\n    -- TODO: Does this overwrite itself?\n    target:delStatusEffect(xi.effect.MAGIC_ATK_BOOST)\n    target:delStatusEffect(xi.effect.MAGIC_DEF_BOOST)\n\n    target:addStatusEffect(xi.effect.MAGIC_ATK_BOOST, { power = buffvalue, duration = duration, origin = pet })\n    target:addStatusEffect(xi.effect.MAGIC_DEF_BOOST, { power = 14 - buffvalue, duration = duration, origin = pet })\n\n    if target:getID() == action:getPrimaryTargetID() then\n        petskill:setMsg(xi.msg.basic.JA_RECEIVES_MAB_MDB)\n    else\n        petskill:setMsg(xi.msg.basic.JA_RECEIVES_MAB_MDB_2)\n    end\n\n    return 0\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/dust_cloud.lua"]={["Path"]="scripts/actions/abilities/pets/dust_cloud.lua",["SHA256"]="73bb79b8c17991580956bf2f2708af9d507f2182c5e6db51c3a2e11136cc344d",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'dust_cloud_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/earthen_fury.lua"]={["Path"]="scripts/actions/abilities/pets/earthen_fury.lua",["SHA256"]="cf2e51d06d5b911077bdaa88a95736e10e9c47a4bb41b42ac37be3701151edd5",["Text"]="-----------------------------------\n-- Earthen Fury\n-- Family: Titan (Player Pet)\n-- Note: Titan's Astral Flow\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage      = pet:getMainLvl() + 2\n    params.fTP             = { 9.0, 9.0, 9.0 }\n    params.int_wSC         = 0.30\n    params.element         = xi.element.EARTH\n    params.attackType      = xi.attackType.MAGICAL\n    params.damageType      = xi.damageType.EARTH\n    params.shadowBehavior  = xi.mobskills.shadowBehavior.WIPE_SHADOWS\n    params.dStatMultiplier = 1.5\n    params.canMagicBurst   = true\n    params.primaryMessage  = xi.msg.basic.USES_JA_TAKE_DAMAGE\n    -- TODO: Should not consume TP\n\n    local info = xi.mobskills.mobMagicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    summoner:setMP(0)\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/earthen_ward.lua"]={["Path"]="scripts/actions/abilities/pets/earthen_ward.lua",["SHA256"]="2010ccf58a29dd44167edfff802b6fa7b38a94e99ec804961a3b262af3adcf1b",["Text"]="-----------------------------------\n-- Earthen Ward\n-- Family: Avatar (Titan)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    local amount = pet:getMainLvl() * 2 + 50\n\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    if target:addStatusEffect(xi.effect.STONESKIN, { power = amount, duration = 900, origin = pet, tier = 3 }) then\n        if target:getID() == action:getPrimaryTargetID() then\n            petskill:setMsg(xi.msg.basic.SKILL_GAIN_EFFECT_2)\n        else\n            petskill:setMsg(xi.msg.basic.JA_GAIN_EFFECT)\n        end\n    else\n        petskill:setMsg(xi.msg.basic.JA_NO_EFFECT_2)\n        return\n    end\n\n    return xi.effect.STONESKIN\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/eclipse_bite.lua"]={["Path"]="scripts/actions/abilities/pets/eclipse_bite.lua",["SHA256"]="7c6f81ec204c8b41bd0d98550b0b24533a650978fdc2280830aa904da94e759d",["Text"]="-----------------------------------\n-- Eclipse Bite\n-- Family: Avatar (Fenrir)\n-- Description: Delivers a threefold attack to a target.\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 3\n    params.fTP               = { 3.269531, 4.085937, 4.902343 } -- TODO: Capture 2000 TP fTP. Using linear scaling for now.\n    params.fTPSubsequentHits = { 3.269531, 4.085937, 4.902343 }\n    params.dex_wSC           = 0.30\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.SLASHING\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_3\n    -- params.accuracyModifier   = { 0, 0, 0 } TODO: Capture accuracy\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/ecliptic_growl.lua"]={["Path"]="scripts/actions/abilities/pets/ecliptic_growl.lua",["SHA256"]="c44c28123ac7ecdd08ccd75545a91064213d45028cbd380d8e6872015b0bb82b",["Text"]="-----------------------------------\n-- Ecliptic Growl\n-- Family: Avatar (Fenrir)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local baseDuration = 180\n    local bonusTime    = utils.clamp(summoner:getSkillLevel(xi.skill.SUMMONING_MAGIC) - 300, 0, 200)\n    local duration     = baseDuration + bonusTime\n\n    local moonCycle = getVanadielMoonCycle()\n\n    local cycleBuffs =\n    {\n        [xi.moonCycle.NEW_MOON]                = 1,\n        [xi.moonCycle.LESSER_WAXING_CRESCENT]  = 2,\n        [xi.moonCycle.GREATER_WAXING_CRESCENT] = 3,\n        [xi.moonCycle.FIRST_QUARTER]           = 4,\n        [xi.moonCycle.LESSER_WAXING_GIBBOUS]   = 5,\n        [xi.moonCycle.GREATER_WAXING_GIBBOUS]  = 6,\n        [xi.moonCycle.FULL_MOON]               = 7,\n        [xi.moonCycle.GREATER_WANING_GIBBOUS]  = 6,\n        [xi.moonCycle.LESSER_WANING_GIBBOUS]   = 5,\n        [xi.moonCycle.THIRD_QUARTER]           = 4,\n        [xi.moonCycle.GREATER_WANING_CRESCENT] = 3,\n        [xi.moonCycle.LESSER_WANING_CRESCENT]  = 2,\n    }\n\n    local buffValue = cycleBuffs[moonCycle]\n\n    -- TODO: Glittering Ruby does not overwrite this.\n    -- This does not overwrite Glittering Ruby.\n    -- This can overwrite itself.\n    -- Unknown how it interacts with STAT_DOWN effects.\n    -- Unknown how it interacts with GAIN/BOOST spells.\n\n    target:addStatusEffect(xi.effect.STR_BOOST, { power = buffValue, duration = duration, origin = pet })\n    target:addStatusEffect(xi.effect.DEX_BOOST, { power = buffValue, duration = duration, origin = pet })\n    target:addStatusEffect(xi.effect.VIT_BOOST, { power = buffValue, duration = duration, origin = pet })\n    target:addStatusEffect(xi.effect.AGI_BOOST, { power = 8-buffValue, duration = duration, origin = pet })\n    target:addStatusEffect(xi.effect.INT_BOOST, { power = 8-buffValue, duration = duration, origin = pet })\n    target:addStatusEffect(xi.effect.MND_BOOST, { power = 8-buffValue, duration = duration, origin = pet })\n    target:addStatusEffect(xi.effect.CHR_BOOST, { power = 8-buffValue, duration = duration, origin = pet })\n\n    if target:getID() == action:getPrimaryTargetID() then\n        petskill:setMsg(xi.msg.basic.STATUS_BOOST)\n    else\n        petskill:setMsg(xi.msg.basic.STATUS_BOOST_2)\n    end\n\n    return 0\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/ecliptic_howl.lua"]={["Path"]="scripts/actions/abilities/pets/ecliptic_howl.lua",["SHA256"]="2561290fc9f76904bab1ad7bf93b4f84d6c01f7f8a86bd8b23dc7db8c5402c0f",["Text"]="-----------------------------------\n-- Ecliptic Howl\n-- Family: Avatar (Fenrir)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local baseDuration = 180\n    local bonusTime    = utils.clamp(summoner:getSkillLevel(xi.skill.SUMMONING_MAGIC) - 300, 0, 200)\n    local duration     = baseDuration + bonusTime\n    local moonCycle    = getVanadielMoonCycle()\n\n    local cycleBuffs =\n    {\n        [xi.moonCycle.NEW_MOON]                = 1,\n        [xi.moonCycle.LESSER_WAXING_CRESCENT]  = 5,\n        [xi.moonCycle.GREATER_WAXING_CRESCENT] = 9,\n        [xi.moonCycle.FIRST_QUARTER]           = 13,\n        [xi.moonCycle.LESSER_WAXING_GIBBOUS]   = 17,\n        [xi.moonCycle.GREATER_WAXING_GIBBOUS]  = 21,\n        [xi.moonCycle.FULL_MOON]               = 25,\n        [xi.moonCycle.GREATER_WANING_GIBBOUS]  = 21,\n        [xi.moonCycle.LESSER_WANING_GIBBOUS]   = 17,\n        [xi.moonCycle.THIRD_QUARTER]           = 13,\n        [xi.moonCycle.GREATER_WANING_CRESCENT] = 9,\n        [xi.moonCycle.LESSER_WANING_CRESCENT]  = 5,\n    }\n\n    local buffValue = cycleBuffs[moonCycle]\n\n    target:delStatusEffect(xi.effect.ACCURACY_BOOST)\n    target:delStatusEffect(xi.effect.EVASION_BOOST)\n    target:addStatusEffect(xi.effect.ACCURACY_BOOST, { power = buffValue, duration = duration, origin = pet })\n    target:addStatusEffect(xi.effect.EVASION_BOOST, { power = 25 - buffValue, duration = duration, origin = pet })\n\n    if target:getID() == action:getPrimaryTargetID() then\n        petskill:setMsg(xi.msg.basic.ACC_EVA_BOOST)\n    else\n        petskill:setMsg(xi.msg.basic.ACC_EVA_BOOST_2)\n    end\n\n    return 0\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/eerie_eye.lua"]={["Path"]="scripts/actions/abilities/pets/eerie_eye.lua",["SHA256"]="03d6fac486d0daea70b050b2dcf982d611bddd3b14a5e8a3182f00bb6cd2545b",["Text"]="-----------------------------------\n-- Eerie Eye\n-- Family: Avatar (Cait Sith)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local messageParams =\n    {\n        messageBypass          = false,\n        messageCantGain        = xi.msg.basic.JA_NO_EFFECT,\n        messageIsImmune        = xi.msg.basic.JA_MISS,\n        messageIsTraitResisted = xi.msg.basic.JA_MISS,\n        messageIsIncompatible  = xi.msg.basic.JA_MISS,\n        messageIsResisted      = xi.msg.basic.JA_MISS,\n        messageIsNotSuccessful = xi.msg.basic.JA_MISS,\n        messageIsSuccessful    = xi.msg.basic.JA_ENFEEB_IS,\n    }\n\n    -- Effects table.\n    local effectTable =\n    {\n        [1] = { effectId = xi.effect.SILENCE, power = 1, duration = 30, magicalElement = xi.element.LIGHT, actorStat = xi.mod.CHR, bonusMacc = xi.summon.getSummoningSkillOverCap(pet) },\n        [2] = { effectId = xi.effect.AMNESIA, power = 1, duration = 15, magicalElement = xi.element.FIRE,  actorStat = xi.mod.CHR, bonusMacc = xi.summon.getSummoningSkillOverCap(pet) },\n    }\n\n    return xi.combat.action.executeMobskillStatusEffect(pet, target, petskill, effectTable, messageParams)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/fantod.lua"]={["Path"]="scripts/actions/abilities/pets/fantod.lua",["SHA256"]="6e913e40eea89f271d47b5b007143df095c4eab5f6491d53c09bf386bbc4e875",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'fantod_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/filamented_hold.lua"]={["Path"]="scripts/actions/abilities/pets/filamented_hold.lua",["SHA256"]="9166255dba306493d47cb3ed72d2f72fd1325bdd19dc2bde48bd5fdcb3c69105",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'filamented_hold_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/fire_ii.lua"]={["Path"]="scripts/actions/abilities/pets/fire_ii.lua",["SHA256"]="b63f391eb14ad9f6353e270cc43ce19fb7c4124ff2e5f2cf5ac88c5120eb6bbd",["Text"]="-----------------------------------\n-- Fire II\n-- Family: Ifrit (Player Pet)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage      = pet:getMainLvl() + 2\n    params.fTP             = { 1.500, 2.750, 3.125 }\n    params.int_wSC         = 0.30\n    params.element         = xi.element.FIRE\n    params.attackType      = xi.attackType.MAGICAL\n    params.damageType      = xi.damageType.FIRE\n    params.shadowBehavior  = xi.mobskills.shadowBehavior.IGNORE_SHADOWS\n    params.dStatMultiplier = 1.5\n    params.canMagicBurst   = true\n    params.primaryMessage  = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobMagicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/fire_iv.lua"]={["Path"]="scripts/actions/abilities/pets/fire_iv.lua",["SHA256"]="21768b0afc665d7cee078c78a439503facac12fff35c6a5cc12f903b22c97228",["Text"]="-----------------------------------\n-- Fire IV\n-- Family: Ifrit (Player Pet)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage      = pet:getMainLvl() + 2\n    params.fTP             = { 3.6250, 5.3125, 6.1250 }\n    params.int_wSC         = 0.30\n    params.element         = xi.element.FIRE\n    params.attackType      = xi.attackType.MAGICAL\n    params.damageType      = xi.damageType.FIRE\n    params.shadowBehavior  = xi.mobskills.shadowBehavior.IGNORE_SHADOWS\n    params.dStatMultiplier = 1.5\n    params.canMagicBurst   = true\n    params.primaryMessage  = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobMagicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/fireball.lua"]={["Path"]="scripts/actions/abilities/pets/fireball.lua",["SHA256"]="0beccf2e4aead3db1bba20628cf70bade937d2df38b40ad736fab596637f9168",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'fireball_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/flame_breath.lua"]={["Path"]="scripts/actions/abilities/pets/flame_breath.lua",["SHA256"]="127ae2fbc8b40871e6f45cb0f3e48a49edaf036a9c1c0f45c6926c8cb113c077",["Text"]="-----------------------------------\n-- Flame Breath\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    return xi.job_utils.dragoon.useDamageBreath(pet, target, petskill, action, xi.damageType.FIRE)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/flaming_crush.lua"]={["Path"]="scripts/actions/abilities/pets/flaming_crush.lua",["SHA256"]="da8ef101fee9942adede36dc68a812e8feeb584aef2b8ad340f07d99f46c0875",["Text"]="-----------------------------------\n-- Flaming Crush\n-- Family: Avatar (Ifrit)\n-- Description: Deals a twofold hybrid Physical/Magical(Fire) attack to a single target.\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage         = pet:getWeaponDmg()\n    params.numHits            = 2\n    params.fTP                = { 6.0, 6.0, 6.0 }\n    params.fTPSubsequentHits  = { 1.0, 1.0, 1.0 }\n    params.str_wSC            = 0.20\n    params.int_wSC            = 0.20\n    params.attackType         = xi.attackType.PHYSICAL\n    params.damageType         = xi.damageType.BLUNT\n    params.hybridSkill        = true\n    params.hybridSkillElement = xi.element.FIRE\n    params.hybridAttackType   = xi.attackType.MAGICAL\n    params.hybridDamageType   = xi.damageType.FIRE\n    params.shadowBehavior     = xi.mobskills.shadowBehavior.NUMSHADOWS_2\n    -- params.accuracyModifier   = { 0, 0, 0 } TODO: Capture accuracy\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    local totalDamage = 0\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        if info.damage > 0 then\n            target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n            totalDamage = totalDamage + info.damage\n        end\n\n        if info.hybridDamage > 0 and target:getHP() > 0 then\n            target:takeDamage(info.hybridDamage, pet, info.hybridAttackType, info.hybridDamageType)\n            totalDamage = totalDamage + info.hybridDamage\n        end\n    end\n\n    return totalDamage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/foot_kick.lua"]={["Path"]="scripts/actions/abilities/pets/foot_kick.lua",["SHA256"]="7c3900d0fe53c73d3bcc893ab4bbf95fdbed21c39aec791d9fe7911c25348bad",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'foot_kick_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/frenzied_rage.lua"]={["Path"]="scripts/actions/abilities/pets/frenzied_rage.lua",["SHA256"]="791a8d78c6b164a91e9c3bd1db90ba54c4d0b69995fc8346cc67a415c47cc625",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'frenzied_rage'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/frogkick.lua"]={["Path"]="scripts/actions/abilities/pets/frogkick.lua",["SHA256"]="7fe6e7d3a4ad46658736daee1567b273b7c6906b571349e94640bc6a9168a38b",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'frogkick_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/frost_armor.lua"]={["Path"]="scripts/actions/abilities/pets/frost_armor.lua",["SHA256"]="54f66e8a6ed104691973cd88d53ff23d55653ea666f8d9610d13f6bc2bd64824",["Text"]="-----------------------------------\n-- Frost Armor\n-- Family: Avatar (Shiva)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    -- TODO: JPWiki says this will overwrite Reprisal. Possibly other spike effects.\n    target:delStatusEffect(xi.effect.ICE_SPIKES)\n\n    local baseDuration = 180\n    local bonusTime    = utils.clamp(summoner:getSkillLevel(xi.skill.SUMMONING_MAGIC) - 300, 0, 200)\n    local duration     = baseDuration + bonusTime\n\n    -- TODO: Does power ever scale?\n    if target:addStatusEffect(xi.effect.ICE_SPIKES, { power = 15, duration = duration, origin = pet }) then\n        if target:getID() == action:getPrimaryTargetID() then\n            petskill:setMsg(xi.msg.basic.SKILL_GAIN_EFFECT_2)\n        else\n            petskill:setMsg(xi.msg.basic.JA_GAIN_EFFECT)\n        end\n    else\n        petskill:setMsg(xi.msg.basic.JA_NO_EFFECT_2)\n        return\n    end\n\n    return xi.effect.ICE_SPIKES\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/frost_breath.lua"]={["Path"]="scripts/actions/abilities/pets/frost_breath.lua",["SHA256"]="500d1812ff642736dcfbb9cf5299ba9a0b59c1bc7b5cc38b50944cd11a861d45",["Text"]="-----------------------------------\n-- Frost Breath\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    return xi.job_utils.dragoon.useDamageBreath(pet, target, petskill, action, xi.damageType.ICE)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/geist_wall.lua"]={["Path"]="scripts/actions/abilities/pets/geist_wall.lua",["SHA256"]="07d29b402789074941bbd9ed69318e8ad37d6f887871bb8e6a434e982c64c060",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'geist_wall_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/geocrush.lua"]={["Path"]="scripts/actions/abilities/pets/geocrush.lua",["SHA256"]="32df53ce366039f907b8995f94a3b7ac28b1dd537e170b02a773ef4a687a659b",["Text"]="-----------------------------------\n-- Geocrush\n-- Family: Titan (Player Pet)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    -- Merit TP bonus.\n    local merits = 0\n\n    if summoner and summoner:isPC() then\n        merits = utils.clamp(summoner:getMerit(xi.merit.GEOCRUSH) - 400, 0, 3000)\n    end\n\n    local params = {}\n\n    params.baseDamage      = pet:getMainLvl() + 2\n    params.fTP             = { 5.3570, 8.0273, 10.7031 }\n    params.fTPBonus        = merits\n    params.int_wSC         = 0.30\n    params.element         = xi.element.EARTH\n    params.attackType      = xi.attackType.MAGICAL\n    params.damageType      = xi.damageType.EARTH\n    params.shadowBehavior  = xi.mobskills.shadowBehavior.NUMSHADOWS_1 -- TODO: Capture shadowBehavior\n    params.dStatMultiplier = 1.5\n    params.canMagicBurst   = true\n    params.primaryMessage  = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobMagicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n\n        xi.mobskills.mobStatusEffectMove(pet, target, xi.effect.STUN, 1, 0, 4)\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/glittering_ruby.lua"]={["Path"]="scripts/actions/abilities/pets/glittering_ruby.lua",["SHA256"]="1f8e5785a8e790b264154ffe9912f0d8089d4c60d46652cdec3cdb669c0b1cf9",["Text"]="-----------------------------------\n-- Glittering Ruby\n-- Family: Avatar (Carbuncle)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    -- Randomly gives STR/DEX/VIT/AGI/INT/MND/CHR\n    -- Can overwrite an existing Glittering Ruby stat bonus\n    local effects =\n    {\n        xi.effect.STR_BOOST,\n        xi.effect.DEX_BOOST,\n        xi.effect.VIT_BOOST,\n        xi.effect.AGI_BOOST,\n        xi.effect.INT_BOOST,\n        xi.effect.MND_BOOST,\n        xi.effect.CHR_BOOST,\n    }\n\n    local effectId     = utils.randomEntry(effects)\n    local effectPower  = 3 + math.floor(pet:getMainLvl() / 5)\n    local baseDuration = 180\n    local bonusTime    = utils.clamp(summoner:getSkillLevel(xi.skill.SUMMONING_MAGIC) - 300, 0, 200)\n    local duration     = baseDuration + bonusTime\n\n    -- TODO: Ecliptic Growl does not overwrite this.\n    -- This does not overwrite Ecliptic Growl.\n    -- This can overwrite itself.\n    -- Unknown how it interacts with STAT_DOWN effects.\n    -- Unknown how it interacts with GAIN/BOOST spells.\n\n    if target:addStatusEffect(effectId, { power = effectPower, duration = duration, origin = pet }) then\n        if target:getID() == action:getPrimaryTargetID() then\n            petskill:setMsg(xi.msg.basic.SKILL_GAIN_EFFECT_2)\n        else\n            petskill:setMsg(xi.msg.basic.JA_GAIN_EFFECT)\n        end\n    else\n        petskill:setMsg(xi.msg.basic.JA_NO_EFFECT_2)\n\n        return\n    end\n\n    return effectId\nend\n\nreturn abilityObject\n"}};
